# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESMÂ-İ HÜSNÂ: ER-RAHMÂN, ER-RAHÎM VE EL-ADL İSİMLERİ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">er-Rahmân (الرَّحْمَنُ)</text>\n  <text x="32" y="98" font-size="11" fill="#334155">• Dünyada inanan veya inanmayan</text>\n  <text x="40" y="114" font-size="11" fill="#334155"><tspan font-weight="bold">bütün canlılara</tspan> ayırt etmeden</text>\n  <text x="40" y="130" font-size="11" fill="#334155">merhamet eden, rızık verendir.</text>\n  <text x="32" y="158" font-size="11" font-weight="bold" fill="#1e3a8a">Ahlaki Yansıması:</text>\n  <text x="32" y="176" font-size="10.5" fill="#475569">İnsanlara, hayvanlara ve doğaya</text>\n  <text x="32" y="192" font-size="10.5" fill="#475569">karşı kuşatıcı bir şefkat ve</text>\n  <text x="32" y="208" font-size="10.5" fill="#475569">merhamet sahibi olmak.</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">er-Rahîm (الرَّحِيمُ)</text>\n  <text x="257" y="98" font-size="11" fill="#334155">• Ahiret gününde iman edip</text>\n  <text x="265" y="114" font-size="11" fill="#334155">salih amel işleyen <tspan font-weight="bold">mümin</tspan></text>\n  <text x="265" y="130" font-size="11" fill="#334155"><tspan font-weight="bold">kullarına</tspan> özel ikramda bulunandır.</text>\n  <text x="257" y="158" font-size="11" font-weight="bold" fill="#14532d">Ahlaki Yansıması:</text>\n  <text x="257" y="176" font-size="10.5" fill="#475569">Her hayırlı işe Besmele ile</text>\n  <text x="257" y="192" font-size="10.5" fill="#475569">başlamak, mümin kardeşlerine</text>\n  <text x="257" y="208" font-size="10.5" fill="#475569">şefkatle yardım elini uzatmak.</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">el-Adl (الْعَدْلُ)</text>\n  <text x="482" y="98" font-size="11" fill="#334155">• Mutlak <tspan font-weight="bold">adalet</tspan> sahibi olan,</text>\n  <text x="490" y="114" font-size="11" fill="#334155">hiç kimseye zerre kadar zulüm</text>\n  <text x="490" y="130" font-size="11" fill="#334155">ve haksızlık etmeyendir.</text>\n  <text x="482" y="158" font-size="11" font-weight="bold" fill="#854d0e">Ahlaki Yansıması:</text>\n  <text x="482" y="176" font-size="10.5" fill="#475569">Akraba veya tanıdık kayırmadan</text>\n  <text x="482" y="192" font-size="10.5" fill="#475569">hakkaniyetle hükmetmek, kul</text>\n  <text x="482" y="208" font-size="10.5" fill="#475569">hakkından titizlikle sakınmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ES-SETTÂR, EL-GAFFÂR, EL-AZÎZ VE ES-SELÂM İSİMLERİ</text>\n  <rect x="20" y="48" width="155" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="97" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#be185d">es-Settâr (السَّتَّارُ)</text>\n  <text x="30" y="98" font-size="10.5" fill="#334155">Kullarının günahlarını,</text>\n  <text x="30" y="114" font-size="10.5" fill="#334155">hatalarını ve kusurlarını</text>\n  <text x="30" y="130" font-size="10.5" font-weight="bold" fill="#9d174d">örten, gizleyendir.</text>\n  <text x="30" y="160" font-size="10.5" font-weight="bold" fill="#831843">Yansıması:</text>\n  <text x="30" y="178" font-size="10" fill="#475569">İnsanların ayıplarını</text>\n  <text x="30" y="194" font-size="10" fill="#475569">ifşa etmeyip örtmek.</text>\n  <rect x="188" y="48" width="155" height="190" rx="8" fill="#f3e8ff" stroke="#a855f7"/>\n  <text x="265" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">el-Gaffâr (الْغَفَّارُ)</text>\n  <text x="198" y="98" font-size="10.5" fill="#334155">Tövbe eden kulların</text>\n  <text x="198" y="114" font-size="10.5" fill="#334155">günahlarını çokça</text>\n  <text x="198" y="130" font-size="10.5" font-weight="bold" fill="#581c87">bağışlayan, affedendir.</text>\n  <text x="198" y="160" font-size="10.5" font-weight="bold" fill="#581c87">Yansıması:</text>\n  <text x="198" y="178" font-size="10" fill="#475569">Kin tutmamak, özür</text>\n  <text x="198" y="194" font-size="10" fill="#475569">dileyeni affetmek.</text>\n  <rect x="356" y="48" width="155" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="433" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">el-Azîz (الْعَزِيزُ)</text>\n  <text x="366" y="98" font-size="10.5" fill="#334155">Mutlak güç, onur ve</text>\n  <text x="366" y="114" font-size="10.5" font-weight="bold" fill="#1e3a8a">üstünlük sahibi,</text>\n  <text x="366" y="130" font-size="10.5" fill="#334155">yenilmeyen galiptir.</text>\n  <text x="366" y="160" font-size="10.5" font-weight="bold" fill="#1e3a8a">Yansıması:</text>\n  <text x="366" y="178" font-size="10" fill="#475569">Yalnız Allah\'a boyun</text>\n  <text x="366" y="194" font-size="10" fill="#475569">eğmek, izzetli yaşamak.</text>\n  <rect x="524" y="48" width="155" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="601" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">es-Selâm (السَّلَامُ)</text>\n  <text x="534" y="98" font-size="10.5" fill="#334155">Her kusurdan uzak,</text>\n  <text x="534" y="114" font-size="10.5" fill="#334155">kullarına <tspan font-weight="bold" fill="#14532d">esenlik, barış</tspan></text>\n  <text x="534" y="130" font-size="10.5" fill="#334155"><tspan font-weight="bold" fill="#14532d">ve güven</tspan> verendir.</text>\n  <text x="534" y="160" font-size="10.5" font-weight="bold" fill="#14532d">Yansıması:</text>\n  <text x="534" y="178" font-size="10" fill="#475569">Elinden ve dilinden</text>\n  <text x="534" y="194" font-size="10" fill="#475569">güven duyulan kul olmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESMÂ-İ HÜSNÂ\'NIN AHLAKA VE İSLAM SANATLARINA YANSIMASI</text>\n  <rect x="25" y="48" width="315" height="192" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Dua ve Ahlaki Bilinç (A\'râf, 180)</text>\n  <text x="40" y="98" font-size="11.5" font-weight="bold" fill="#1e3a8a">"En güzel isimler (Esmâ-i Hüsnâ) Allah\'ındır;</text>\n  <text x="40" y="115" font-size="11.5" font-weight="bold" fill="#1e3a8a">o hâlde O\'na o güzel isimlerle dua edin..."</text>\n  <text x="40" y="142" font-size="11.5" fill="#334155">• Rızık isterken <tspan font-weight="bold">er-Rezzâk / er-Rahmân</tspan>,</text>\n  <text x="40" y="162" font-size="11.5" fill="#334155">• Bağışlanma dilerken <tspan font-weight="bold">el-Gaffâr / el-Afüvv</tspan>,</text>\n  <text x="40" y="182" font-size="11.5" fill="#334155">• Huzur ve güven isterken <tspan font-weight="bold">es-Selâm</tspan>,</text>\n  <text x="40" y="202" font-size="11.5" fill="#334155">• Ayıpların örtülmesi için <tspan font-weight="bold">es-Settâr</tspan> ismiyle</text>\n  <text x="48" y="220" font-size="11.5" fill="#334155">Yüce Allah\'a yönelip dua edilir.</text>\n  <rect x="360" y="48" width="315" height="192" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Geleneksel Sanatlarda Esmâ-i Hüsnâ</text>\n  <text x="375" y="100" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#854d0e">Hüsn-i Hat (Güzel Yazı Sanatı):</tspan></text>\n  <text x="383" y="117" font-size="11" fill="#334155">Allah\'ın güzel isimlerinin kamış kalem ve</text>\n  <text x="383" y="133" font-size="11" fill="#334155">is mürekkebiyle estetik ölçülerle yazılmasıdır.</text>\n  <text x="375" y="160" font-size="11.5" fill="#334155">• <tspan font-weight="bold" fill="#854d0e">Tezhip (Altınlama Sanatı):</tspan></text>\n  <text x="383" y="177" font-size="11" fill="#334155">Hat levhalarının ve mushaf sayfalarının</text>\n  <text x="383" y="193" font-size="11" fill="#334155">altın tozu ve bitkisel motiflerle süslenmesidir.</text>\n  <text x="375" y="220" font-size="11" font-weight="bold" fill="#15803d">• Ebru ve Çini sanatlarında da yaşatılır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
